describe('Table Column Sort Direction Indicator', () => {
    beforeEach(() => {
        cy.visit('/table'); // Adjust the URL to your application's table page
    });

    it('should display an ascending sort arrow when the column is sorted in ascending order', () => {
        cy.get('th.sortable').first().click(); // Click to sort the first column
        cy.get('th.sortable').first().find('.sort-arrow').should('have.class', 'ascending'); // Check for ascending arrow
    });

    it('should display a descending sort arrow when the column is sorted in descending order', () => {
        cy.get('th.sortable').first().click(); // Click to sort the first column
        cy.get('th.sortable').first().click(); // Click again to sort in descending order
        cy.get('th.sortable').first().find('.sort-arrow').should('have.class', 'descending'); // Check for descending arrow
    });
});
